import 'package:pulumi/pulumi.dart' as pulumi;
import 'allowed_client_response.dart';
import 'nfs_share_args.dart';

/// Create an NFS share.
class NfsShare extends pulumi.CustomResource {
  /// List of allowed access points.
  late final pulumi.Output<List<AllowedClientResponse>> allowedClients;

  /// Labels as key value pairs.
  late final pulumi.Output<Map<String, String>> labels;
  late final pulumi.Output<String> location;

  /// Immutable. The name of the NFS share.
  late final pulumi.Output<String> name;

  /// An identifier for the NFS share, generated by the backend. This field will be deprecated in the future, use `id` instead.
  late final pulumi.Output<String> nfsShareId;

  /// Immutable. Pod name. Pod is an independent part of infrastructure. NFSShare can only be connected to the assets (networks, instances) allocated in the same pod.
  late final pulumi.Output<String> pod;
  late final pulumi.Output<String> project;

  /// The requested size, in GiB.
  late final pulumi.Output<String> requestedSizeGib;

  /// The state of the NFS share.
  late final pulumi.Output<String> state;

  /// Immutable. The storage type of the underlying volume.
  late final pulumi.Output<String> storageType;

  /// The underlying volume of the share. Created automatically during provisioning.
  late final pulumi.Output<String> volume;

  NfsShare(
    String name, {
    NfsShareArgs? args,
    pulumi.CustomResourceOptions? options,
  }) : super(
          'google-native:baremetalsolution/v2:NfsShare',
          name,
          pulumi.Input.mapToInputs(args?.toMap() ?? const {}),
          options ?? pulumi.CustomResourceOptions(),
        ) {
    this.allowedClients =
        registerOutput<List<AllowedClientResponse>>('allowedClients');
    this.labels = registerOutput<Map<String, String>>('labels');
    this.location = registerOutput<String>('location');
    this.name = registerOutput<String>('name');
    this.nfsShareId = registerOutput<String>('nfsShareId');
    this.pod = registerOutput<String>('pod');
    this.project = registerOutput<String>('project');
    this.requestedSizeGib = registerOutput<String>('requestedSizeGib');
    this.state = registerOutput<String>('state');
    this.storageType = registerOutput<String>('storageType');
    this.volume = registerOutput<String>('volume');
  }
}
